from collections import Counter
def f(g):
    h,w=len(g),len(g[0])
    def iso(i,j):
        v=g[i][j]
        return not(i>0 and g[i-1][j]==v or i<h-1 and g[i+1][j]==v or j>0 and g[i][j-1]==v or j<w-1 and g[i][j+1]==v)
