    for i in range(h):
        for j in range(w):
            if iso(i,j):
                nb=[g[i-1][j] if i>0 else None, g[i+1][j] if i<h-1 else None, g[i][j-1] if j>0 else None, g[i][j+1] if j<w-1 else None]
